    degrees = np.ones(N, dtype=float)
    for i0 in range(m):
        for j0 in range(i0+1, m):
            G[i0].add(j0); G[j0].add(i0)
            degrees[i0] += 1; degrees[j0] += 1
    for i_new in range(m, N):
        probs = degrees[:i_new] / degrees[:i_new].sum()
        chosen = set()
        while len(chosen) < m:
            j = int(self.rng.choice(i_new, p=probs))
            chosen.add(j)
        for j in chosen:
            G[i_new].add(j); G[j].add(i_new)
            degrees[i_new] += 1; degrees[j] += 1
    for i, p in enumerate(people):
        p.network_neighbors = list(G[i])
elif net_type == "erdos_renyi":
    p_edge = min(1.0, avg_degree / max(1, N-1))
    G = [set() for _ in range(N)]
    for i in range(N):
        for j in range(i+1, N):
            if self.rng.random() < p_edge:
                G[i].add(j); G[j].add(i)
    for i, p in enumerate(people):
        p.network_neighbors = list(G[i])
